// CD pulse-arc welder firmware model, controls rev B: bank on GPIO1, ARM switch on GPIO3, DUMP button on GPIO20.
// K1 (GPIO19) feeds the charger; K2 (GPIO18) keeps the dump resistor R6 off the bank only while energized.

fn fmt1(x) {
    let neg = x < 0.0;
    let t = (x.abs() * 10.0).round().to_int();
    let s = `${t / 10}.${t % 10}`;
    if neg { "-" + s } else { s }
}

fn maxf(a, b) { if a > b { a } else { b } }

// Two-point calibration: ADC millivolts -> bank volts, both points read off a meter.
fn bank_volts(mv, k) {
    k.v_lo + (mv - k.mv_lo) * (k.v_hi - k.v_lo) / (k.mv_hi - k.mv_lo)
}

fn state_color(st) {
    switch st {
        "SAFE" => [40, 60, 140],
        "ARMING" => [150, 110, 0],
        "CHARGE" => [200, 130, 0],
        "READY" => [0, 150, 70],
        "HOLD" => [0, 110, 170],
        "DUMPING" => [130, 40, 150],
        _ => [200, 0, 0]
    }
}

fn hint(st, fault, arm_on, latched) {
    switch st {
        "SAFE" => {
            if latched && arm_on { "ARM off, then on" } else if arm_on { "arming..." } else { "switch ARM on" }
        },
        "ARMING" => "opening dump",
        "CHARGE" => "charging bank...",
        "READY" => "touch pen to work",
        "HOLD" => "welded - lift pen",
        "DUMPING" => "dumping bank...",
        "FAULT" => {
            if fault == "DUMP STALLED" { "switch ARM off" } else { fault }
        },
        _ => ""
    }
}

// States in which the charger may run and K2 holds the dump open.
fn is_armed_state(st) {
    st == "ARMING" || st == "CHARGE" || st == "READY" || st == "HOLD"
}

fn paint_header(st) {
    let c = state_color(st);
    lcd_rect(0, 0, 128, 18, c[0], c[1], c[2]);
    lcd_text(4, 5, "CD WELDER", 255, 255, 255);
    lcd_text(124 - st.len * 6, 5, st, 255, 255, 255);
}

fn paint_footer(text) {
    lcd_rect(0, 112, 128, 16, 16, 18, 30);
    lcd_text(4, 115, text, 225, 225, 235);
}

fn paint_line(y, text, r, g, b) {
    lcd_rect(0, y - 2, 128, 13, 6, 8, 16);
    lcd_text(4, y, text, r, g, b);
}

fn paint_bar(v, set, full) {
    let w = (v / full * 120.0).to_int();
    if w < 0 { w = 0; }
    if w > 120 { w = 120; }
    lcd_rect(4, 74, 120, 8, 30, 34, 48);
    if w > 0 {
        if v >= set - 4.0 { lcd_rect(4, 74, w, 8, 60, 220, 110); } else { lcd_rect(4, 74, w, 8, 240, 160, 40); }
    }
    let s = (set / full * 120.0).to_int();
    lcd_rect(4 + s, 71, 2, 14, 255, 255, 255);
}

fn on_start() {
    this.k = #{
        adc_pin: 1,          // bank sense: R1-R4 tap through R5 (ADC1 ch1)
        arm_pin: 3,          // ARM switch sense: R7 47 k / R8 10 k from S1's output (ADC1 ch3)
        dump_pin: 20,        // DUMP button S2 to GND, internal pull-up
        boot_pin: 9,         // on-board BOOT: short press steps the set point, 1 s hold clears a fault (no arming)
        mv_lo: 0.0,          // calibration point 1: ADC mV ...
        v_lo: 0.0,           // ... and the meter's bank volts
        mv_hi: 1986.8,       // calibration point 2 (ideal 2/302 divider at 300 V)
        v_hi: 300.0,
        arm_ratio: 5.7,      // supply volts per ADC volt (57/10)
        arm_on_v: 8.0,       // ARM switch reads ON above this supply ...
        arm_off_v: 6.0,      // ... and OFF below this
        presets: [120.0, 180.0, 240.0, 280.0],
        margin_v: 3.0,       // open K1 this far below the set point
        relay_s: 0.010,      // K1 release time added to the sample interval
        cutoff_v: 310.0,     // hard cutoff
        timeout_ms: 30000,   // longest charge
        weld_drop_v: 20.0,   // a sample-to-sample drop this big is a weld
        holdoff_ms: 1500,    // K1 stays open after a weld
        topup_v: 8.0,        // recharge when READY sags this far
        stuck_ms: 800,       // charging that cannot pass stuck_v: pen on the work or a short
        stuck_v: 30.0,
        safe_v: 5.0,         // the bank counts as empty below this ...
        safe_ms: 200,        // ... for this long
        k2_delay_ms: 20,     // K2 releases this long after K1 opens
        settle_ms: 60,       // K2 energized this long before K1 may close
        stall_half_ms: 1000, // a dump must halve the bank within this ...
        stall_ms: 3000,      // ... and be under stall_v within this
        stall_v: 30.0,
        long_ms: 1000,       // BOOT hold that clears a fault
        c_f: 0.00019,        // bank capacitance
        boot_ms: 1000,       // ARM readings this soon after boot do not release the latch
        full_v: 330.0        // bar-graph full scale (cap rating)
    };
    this.st = "SAFE";
    this.t_state = millis();
    this.t_boot = millis();
    this.preset = 2;
    this.set_v = this.k.presets[2];
    this.v = 0.0;
    this.t_prev = millis();
    this.rate = 0.0;         // rise rate in V/s: positive slopes, lightly smoothed
    this.dt_s = 0.0;         // interval between the last two fresh samples
    this.inc = 0.0;          // last per-sample rise while charging
    this.step = 0.0;         // typical per-sample rise near the set point
    this.welds = 0;
    this.last_j = 0.0;
    this.fault = "";
    this.arm_on = false;     // ARM switch state after hysteresis
    this.latched = true;     // boot, DUMP and fault latch: released while ARM reads OFF
    this.dump_down = false;  // DUMP held: nothing arms
    this.fault_ack = false;  // ARM went ON -> OFF during a fault
    this.dump_req = false;
    this.k2_on = false;
    this.t_k2 = 0;
    this.k2_off_at = -1;     // millis when K2 is due to release, -1 = none
    this.dump_v0 = 0.0;
    this.t_dump = millis();
    this.t_low = -1;         // millis the bank first read empty, -1 = not empty
    this.boot_down = false;
    this.boot_long = false;
    this.t_press = 0;
    this.hint_shown = "";
    this.v_shown = -999.0;
    this.s_shown = -999.0;
    this.t_paint = 0;
    k1.off();
    k2.off();
    pin(this.k.adc_pin).watch_analog(5);
    pin(this.k.arm_pin).watch_analog(20);
    pin(this.k.dump_pin).input_pullup();
    pin(this.k.boot_pin).input_pullup();
    lcd_init(6, 7, 14, 15, 21);
    lcd_clear(6, 8, 16);
    paint_header("SAFE");
    paint_line(58, `SET   ${fmt1(this.set_v)} V`, 255, 220, 90);
    paint_line(90, "WELDS 0", 200, 200, 210);
    this.hint_shown = hint("SAFE", "", false, false);
    paint_footer(this.hint_shown);
    rgb(8, 12, 30);
    log("K1 and K2 released at boot: bank dumping, disarmed. ARM OFF -> ON arms.");
}

fn on_tick(dt_ms) {
    if this.st == () { return; }
    let k = this.k;
    let now = millis();
    let mv = pin(k.adc_pin).millivolts().to_float();
    let v = bank_volts(mv, k);

    // ARM switch with hysteresis; reading OFF with DUMP up releases the latch.
    let supply = pin(k.arm_pin).millivolts().to_float() * k.arm_ratio / 1000.0;
    let was_on = this.arm_on;
    if !was_on && supply > k.arm_on_v { this.arm_on = true; }
    if was_on && supply < k.arm_off_v { this.arm_on = false; }
    if was_on && !this.arm_on && this.st == "FAULT" { this.fault_ack = true; }
    if this.arm_on { this.fault_ack = false; }
    if !this.arm_on && !this.dump_down && now - this.t_boot >= k.boot_ms { this.latched = false; }
    if this.arm_on != was_on {
        let word = if this.arm_on { "ON" } else { "OFF" };
        log(`ARM switch ${word} (${fmt1(supply)} V)`);
    }

    // BOOT held for long_ms requests a fault clear.
    let clear = false;
    if this.boot_down && !this.boot_long && now - this.t_press >= k.long_ms {
        this.boot_long = true;
        clear = true;
    }

    // Fresh samples update the rise rate; a big drop between samples is a weld.
    let weld = false;
    if v != this.v {
        let dt = (now - this.t_prev).to_float() / 1000.0;
        if this.v - v >= k.weld_drop_v {
            weld = true;
            this.last_j = 0.5 * k.c_f * (this.v * this.v - v * v);
        }
        if dt > 0.0 {
            let r = maxf((v - this.v) / dt, 0.0);
            this.rate = if this.rate > 0.0 { 0.5 * (this.rate + r) } else { r };
            this.dt_s = dt;
        }
        this.inc = maxf(v - this.v, 0.0);
        if this.st == "CHARGE" && v > this.set_v * 0.6 && this.inc > 0.0 { this.step = this.inc; }
        this.v = v;
        this.t_prev = now;
    }

    let st = this.st;
    let next = st;
    let age = now - this.t_state;
    let armed = this.arm_on && !this.latched && !this.dump_down;
    if v > k.cutoff_v && st != "FAULT" {
        next = "FAULT";
        this.fault = "OVER 310 V";
    } else if st == "FAULT" {
        if (this.fault_ack || clear) && v < k.cutoff_v {
            next = if v >= k.safe_v { "DUMPING" } else { "SAFE" };
            this.fault_ack = false;
            this.latched = true;
            log("fault cleared");
        }
    } else if is_armed_state(st) && (this.dump_req || !armed) {
        next = "DUMPING";
    } else {
        switch st {
            "SAFE" => {
                if v >= k.safe_v {
                    next = "DUMPING";
                } else if armed {
                    next = "ARMING";
                }
            },
            "DUMPING" => {
                let t = now - this.t_dump;
                if v < k.safe_v {
                    if this.t_low < 0 { this.t_low = now; }
                    if now - this.t_low >= k.safe_ms { next = "SAFE"; }
                } else {
                    this.t_low = -1;
                    if (t >= k.stall_half_ms && v > this.dump_v0 * 0.5) || (t >= k.stall_ms && v > k.stall_v) {
                        next = "FAULT";
                        this.fault = "DUMP STALLED";
                    }
                }
            },
            "ARMING" => {
                if v >= k.safe_v {
                    next = "DUMPING";
                } else if this.k2_on && now - this.t_k2 >= k.settle_ms {
                    next = "CHARGE";
                }
            },
            "CHARGE" => {
                // Bank volts after the next sample interval plus K1's release time.
                let predicted = v + this.rate * (k.relay_s + this.dt_s);
                if weld {
                    next = "HOLD";
                } else if predicted >= this.set_v - k.margin_v {
                    next = "READY";
                } else if age > k.timeout_ms {
                    next = "FAULT";
                    this.fault = "CHARGE TIMEOUT";
                } else if age > k.stuck_ms && v < k.stuck_v {
                    next = "FAULT";
                    this.fault = "NO RISE - SHORT?";
                }
            },
            "READY" => {
                if weld {
                    next = "HOLD";
                } else if v < this.set_v - maxf(k.topup_v, this.step) {
                    // Top up only once the bank has sagged by at least one charge step.
                    next = "CHARGE";
                }
            },
            "HOLD" => {
                if age >= k.holdoff_ms { next = "CHARGE"; }
            },
            _ => {}
        }
    }
    this.dump_req = false;

    if next != st {
        this.st = next;
        this.t_state = now;
        switch next {
            "ARMING" => {
                k2.on();
                this.k2_on = true;
                this.t_k2 = now;
                this.k2_off_at = -1;
            },
            "CHARGE" => {
                // K1 closes only once K2 has held the dump open for settle_ms.
                if this.k2_on && now - this.t_k2 >= k.settle_ms { k1.on(); } else { k1.off(); }
                this.rate = 0.0;
            },
            "DUMPING" => {
                k1.off();
                if this.k2_on { this.k2_off_at = now + k.k2_delay_ms; }
                this.dump_v0 = v;
                this.t_dump = now;
                this.t_low = -1;
            },
            "FAULT" => {
                k1.off();
                if this.k2_on { this.k2_off_at = now + k.k2_delay_ms; }
            },
            _ => { k1.off(); }
        }
        let c = state_color(next);
        rgb(c[0] / 5, c[1] / 5, c[2] / 5);
        paint_header(next);
        if next == "HOLD" && weld {
            this.welds += 1;
            paint_line(90, `WELDS ${this.welds}  ${fmt1(this.last_j)} J`, 200, 200, 210);
            log(`weld #${this.welds}: ${fmt1(this.last_j)} J from the bank`);
        }
        if next == "FAULT" {
            paint_line(90, this.fault, 255, 90, 90);
            log(`FAULT: ${this.fault} - K1 open, K2 released`);
        } else if st == "FAULT" {
            paint_line(90, `WELDS ${this.welds}`, 200, 200, 210);
            this.fault = "";
        }
        log(`${st} -> ${next} at ${fmt1(v)} V`);
    }

    // K2 releases k2_delay_ms after K1 opened.
    if this.k2_off_at >= 0 && now >= this.k2_off_at {
        k2.off();
        this.k2_on = false;
        this.k2_off_at = -1;
    }

    let h = hint(this.st, this.fault, this.arm_on, this.latched);
    if h != this.hint_shown {
        this.hint_shown = h;
        paint_footer(h);
    }

    if now - this.t_paint >= 60 && ((v - this.v_shown).abs() >= 0.5 || (supply - this.s_shown).abs() >= 0.5) {
        this.v_shown = v;
        this.s_shown = supply;
        this.t_paint = now;
        let e = 0.5 * k.c_f * v * v;
        paint_line(24, `BANK  ${fmt1(v)} V`, 255, 255, 255);
        paint_line(40, `E     ${fmt1(e)} J`, 170, 200, 255);
        paint_bar(v, this.set_v, k.full_v);
        paint_line(100, `ADC ${mv.to_int()} ARM ${fmt1(supply)}V`, 110, 120, 150);
    }
}

// DUMP disarms and latches; BOOT steps the set point on a short press (a 1 s hold clears a fault in on_tick).
fn on_pin(gpio, high) {
    if this.st == () { return; }
    let k = this.k;
    if gpio == k.dump_pin {
        this.dump_down = !high;
        if !high {
            this.latched = true;
            this.dump_req = true;
            log("DUMP pressed: disarmed until the ARM switch goes OFF -> ON");
        }
        return;
    }
    if gpio != k.boot_pin { return; }
    if !high {
        this.boot_down = true;
        this.boot_long = false;
        this.t_press = millis();
        return;
    }
    if !this.boot_down { return; }
    this.boot_down = false;
    if this.boot_long { return; }
    this.preset = (this.preset + 1) % k.presets.len();
    this.set_v = k.presets[this.preset];
    paint_line(58, `SET   ${fmt1(this.set_v)} V`, 255, 220, 90);
    this.v_shown = -999.0;
    log(`set point ${fmt1(this.set_v)} V`);
}
